<?php
 namespace Pterodactyl\Services\Dezerx\Ai; class PanelResponse { public function __construct( public readonly int $status, public readonly ?array $json, public readonly string $body, ) { } public function ok(): bool { return $this->status >= 200 && $this->status < 300; } public function attributes(): array { return (array) ($this->json['attributes'] ?? []); } public function items(): array { $rows = $this->json['data'] ?? (array_is_list($this->json ?? []) ? $this->json : []); return array_values(array_filter(array_map( fn (mixed $row) => is_array($row) ? ($row['attributes'] ?? $row) : null, (array) $rows, ), fn (mixed $row) => $row !== null)); } public function meta(string $key, mixed $default = null): mixed { return data_get($this->json, 'meta.' . $key, $default); } public function error(): string { $details = []; foreach ((array) ($this->json['errors'] ?? []) as $error) { $detail = trim((string) ($error['detail'] ?? '')); if ($detail !== '' && !in_array($detail, $details, true)) { $details[] = $detail; } } $detail = implode(' ', array_slice($details, 0, 5)); if ($detail === '' && is_string($this->json['message'] ?? null)) { $detail = trim($this->json['message']); } return match (true) { $this->status === 401 => 'This person is not signed in any more.', $this->status === 403 => $detail !== '' && !str_contains(strtolower($detail), 'this action is unauthorized') ? $detail : 'Their account is not allowed to do that on this server. A subuser only has the permissions the owner gave them.', $this->status === 404 => 'That was not found. Either it does not exist, or that part of the panel is not turned on for this server\'s game.', $this->status === 429 => 'Too many requests of that kind in a short time. Wait a minute before trying it again.', $this->status >= 500 && $detail === '' => 'The panel could not finish that. The server\'s node may be unreachable right now.', default => $detail !== '' ? $detail : 'The panel answered with HTTP ' . $this->status . '.', }; } } 